def solve(data):
    packages = data["packages"]
    roots = data["roots"]
    names = sorted(packages)
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})

    if any(name not in packages for name in roots):
        return {"error": "unsatisfiable"}

    constraints = {
        name: [(bounds[0], bounds[1])]
        for name, bounds in roots.items()
    }
    best_key = None
    best_versions = None

    def search(assigned, active_constraints):
        nonlocal best_key, best_versions

        unresolved = set(active_constraints) - set(assigned)
        if not unresolved:
            versions = {
                name: row["version"]
                for name, row in assigned.items()
            }
            key = tuple(versions.get(name, -1) for name in names)
            if best_key is None or key > best_key:
                best_key = key
                best_versions = versions
            return

        name = min(unresolved)
        for row in choose(
            packages[name],
            active_constraints[name],
            blocked.get(name, ()),
            pins.get(name),
        ):
            next_assigned = dict(assigned)
            next_assigned[name] = row
            next_constraints = {
                package: list(ranges)
                for package, ranges in active_constraints.items()
            }
            feasible = True

            for dependency in row.get("deps", []):
                dep_name = dependency["name"]
                if dep_name not in packages:
                    feasible = False
                    break

                low, high = dependency["min"], dependency["max"]
                next_constraints.setdefault(dep_name, []).append((low, high))
                if dep_name in next_assigned:
                    version = next_assigned[dep_name]["version"]
                    if not low <= version <= high:
                        feasible = False
                        break

            if feasible:
                search(next_assigned, next_constraints)

    search({}, constraints)
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}
